def check_key(dictionary, key):
    if key in dictionary:
        return True
    for value in dictionary.values():
        if isinstance(value, dict):
            if check_key(value, key):
                return True
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict) and check_key(item, key):
                    return True
    return False

def find_all_unique_values(d):
    seen = set()
    unique_values = []
    for value in d.values():
        if value not in seen:
            seen.add(value)
            unique_values.append(value)
    return unique_values

def find_missing_positive(nums: list[int]) -> int:
    """
    Returns the smallest positive integer missing from the given list.

    If all integers are non-positive, returns 1.
    """
    positive_set = {num for num in nums if num > 0}
    missing = 1
    while missing in positive_set:
        missing += 1
    return missing

def max_subarray_sum(numbers, k):
    # Check if input is valid
    if not numbers or k <= 0 or k > len(numbers):
        return None  # or raise ValueError

    current_sum = sum(numbers[:k])  # Sum of the first window
    max_sum = current_sum

    # Slide the window through the array
    for i in range(k, len(numbers)):
        current_sum = current_sum - numbers[i - k] + numbers[i]
        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum

import math

def is_prime(n: int) -> bool:
    """
    Checks if a given integer is a prime number.

    Args:
        n: The integer to check for primality.

    Returns:
        True if n is prime, False otherwise.
    """
    if n <= 1:
        return False
    elif n == 2:
        return True
    elif n % 2 == 0:
        return False
    max_divisor = math.isqrt(n)
    for i in range(3, max_divisor + 1, 2):
        if n % i == 0:
            return False
    return True

def permutations(s):
    """Return all permutations of the input string."""
    if len(s) == 0:
        return []
    elif len(s) == 1:
        return [s]
    result = []
    for i, char in enumerate(s):
        remaining = s[:i] + s[i+1:]
        for perm in permutations(remaining):
            result.append(char + perm)
    return result

