def bubble_sort(arr):
    arr = arr.copy()
    n = len(arr)
    swapped = True
    while swapped:
        swapped = False
        for j in range(n - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
    return arr

