from collections import deque

def generate_strings(n: int) -> list[str]:
    """
    Generate all possible lowercase strings of length n with no consecutive repeating characters.

    Args:
    n: The length of the strings to generate.

    Returns:
    A list of all valid strings.
    """
    if n == 0:
        return []
    result = []
    queue = deque([c for c in 'abcdefghijklmnopqrstuvwxyz'])
    while queue and len(queue[0]) < n:
        current = queue.popleft()
        for c in 'abcdefghijklmnopqrstuvwxyz':
            if c != current[-1]:
                queue.append(current + c)
    return list(queue)

